"""Isolated report process; all input paths are generated by report_runtime."""

import base64
import json
import os
import re
import shutil
import subprocess
import sys
from pathlib import Path

from bisheng.common.utils.report_document import render_docx, render_html
from bisheng.tool.domain.services.report_validation import validate_artifact


def soffice_path():
    configured = os.environ.get("BISHENG_SOFFICE_PATH")
    candidates = [configured, shutil.which("soffice"), shutil.which("libreoffice")]
    if os.name == "nt":
        candidates += [
            str(Path(os.environ.get("ProgramFiles", "C:/Program Files")) / "LibreOffice/program/soffice.exe")
        ]
    return next((path for path in candidates if path and Path(path).is_file()), None)


def check_cjk_font(source):
    if not re.search(r"[\u3040-\u30ff\u3400-\u9fff\uac00-\ud7af]", source):
        return "not-required"
    if os.name == "nt":
        fonts = Path(os.environ.get("WINDIR", "C:/Windows")) / "Fonts"
        for name in ("msyh.ttc", "msjh.ttc", "simsun.ttc", "simhei.ttf", "NotoSansCJK-Regular.ttc"):
            if (fonts / name).is_file():
                return name
    elif executable := shutil.which("fc-match"):
        result = subprocess.run(
            [executable, "-f", "%{lang}", ":lang=zh-cn"], capture_output=True, timeout=5, shell=False
        )
        if result.returncode == 0 and "zh" in result.stdout.decode("utf-8", errors="replace").split("|"):
            return "fontconfig-cjk"
        if result.returncode == 0 and "zh-cn" in result.stdout.decode("utf-8", errors="replace"):
            return "fontconfig-cjk"
    raise RuntimeError("PDF CJK font unavailable; install Noto Sans CJK/WenQuanYi or Microsoft YaHei")


def render_pdf(source, resources, directory):
    cjk_font = check_cjk_font(source)
    engine = os.environ.get("BISHENG_REPORT_PDF_ENGINE", "auto")
    if engine not in {"auto", "chromium", "libreoffice"}:
        raise ValueError("Unknown BISHENG_REPORT_PDF_ENGINE")
    if engine != "libreoffice":
        from playwright.sync_api import sync_playwright

        with sync_playwright() as playwright:
            executable = os.environ.get("BISHENG_REPORT_CHROMIUM_PATH") or playwright.chromium.executable_path
            if Path(executable).is_file():
                browser = playwright.chromium.launch(executable_path=executable, headless=True)
                try:
                    page = browser.new_page()
                    # No report may trigger local or remote requests, including fonts and styles.
                    page.route("**/*", lambda route: route.abort())
                    page.set_content(render_html(source, resources), wait_until="load", timeout=30000)
                    page.evaluate("document.fonts.ready")
                    return page.pdf(format="A4", print_background=True, prefer_css_page_size=True), {
                        "engine": "chromium",
                        "cjk_font": cjk_font,
                    }
                finally:
                    browser.close()
            if engine == "chromium":
                raise RuntimeError("Configured Chromium is unavailable; install it in the deployment image")
    executable = soffice_path()
    if not executable:
        raise RuntimeError("PDF renderer unavailable: configure Chromium or LibreOffice")
    docx = directory / "report.docx"
    docx.write_bytes(render_docx(source, resources))
    profile = directory / "lo-profile"
    result = subprocess.run(
        [
            executable,
            f"-env:UserInstallation={profile.resolve().as_uri()}",
            "--headless",
            "--nologo",
            "--nodefault",
            "--nofirststartwizard",
            "--convert-to",
            "pdf",
            "--outdir",
            str(directory),
            str(docx),
        ],
        capture_output=True,
        timeout=100,
        shell=False,
    )
    output = directory / "report.pdf"
    if result.returncode or not output.is_file():
        raise RuntimeError("LibreOffice did not produce a PDF")
    return output.read_bytes(), {"engine": "libreoffice", "cjk_font": cjk_font}


def main(directory):
    folder = Path(directory)
    payload = json.loads((folder / "input.json").read_text(encoding="utf-8"))
    resources = {key: base64.b64decode(value) for key, value in payload["resources"].items()}
    target = payload["target"]
    engine_info = {}
    if target == "validate":
        files = payload["files"]
        manifest = validate_artifact(files[0][0], base64.b64decode(files[0][1], validate=True))
        for name, encoded in files[1:]:
            validate_artifact(name, base64.b64decode(encoded, validate=True))
        manifest["resources"] = payload["references"]
        (folder / "manifest.json").write_text(json.dumps(manifest), encoding="utf-8")
        return
    if target == "docx":
        result = render_docx(payload["source"], resources)
    elif target == "pdf":
        result, engine_info = render_pdf(payload["source"], resources, folder)
    elif target == "html":
        result = render_html(payload["source"], resources).encode("utf-8")
    else:
        raise ValueError("Unsupported report target")
    manifest = validate_artifact("report." + target, result)
    manifest.update(engine_info)
    (folder / "output.bin").write_bytes(result)
    (folder / "manifest.json").write_text(json.dumps(manifest), encoding="utf-8")


if __name__ == "__main__":
    if sys.platform == "linux":
        import ctypes
        import signal

        # Reap descendants even if the API/worker process itself is terminated.
        signal.signal(signal.SIGTERM, lambda *_: os.killpg(os.getpgrp(), signal.SIGKILL))
        ctypes.CDLL(None).prctl(1, signal.SIGTERM)
        if os.getppid() == 1:
            os.killpg(os.getpgrp(), signal.SIGKILL)
    main(sys.argv[1])
